-- Runs after the platform security suite, inside BEGIN/ROLLBACK only.
reset role;
select set_config('aura.delete_clinic_id',gen_random_uuid()::text,true);
insert into public.aura_clinics(id,owner_id,name,data) values(current_setting('aura.delete_clinic_id')::uuid,current_setting('aura.uid1')::uuid,'Clínica descartável',current_setting('aura.onboarding_fixture')::jsonb);
insert into public.aura_members(clinic_id,email,role) values(current_setting('aura.delete_clinic_id')::uuid,'security-one@example.invalid','manager');
insert into public.aura_history(clinic_id,actor,action,data,revision) values(current_setting('aura.delete_clinic_id')::uuid,'security-one@example.invalid','Fixture','{}',0);
select set_config('aura.keep_users',(select count(*)::text from auth.users),true),set_config('aura.keep_licenses',(select count(*)::text from aura_private.licenses),true);
set local role anon;
select pg_temp.denied('delete_preview',current_setting('aura.delete_clinic_id')::uuid,'{}');
reset role;set local role authenticated;
select pg_temp.as_user('2','aal2');
select pg_temp.denied('delete_preview',current_setting('aura.delete_clinic_id')::uuid,'{}');
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,'{}');
select pg_temp.as_user('1','aal2');
select set_config('aura.clinic_delete_preview',public.aura_rpc('delete_preview',current_setting('aura.delete_clinic_id')::uuid,'{}')::text,true);
select pg_temp.check_ok((current_setting('aura.clinic_delete_preview')::jsonb->>'history')::int=1,'preview reports history to delete');
select set_config('aura.clinic_delete_body',jsonb_build_object('confirmation','Clínica descartável','confirmed',true,'preview',current_setting('aura.clinic_delete_preview')::jsonb,'requestId',gen_random_uuid())::text,true);
select pg_temp.as_user('1','aal1');
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,current_setting('aura.clinic_delete_body')::jsonb);
select pg_temp.as_user('1','aal2');
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,jsonb_set(current_setting('aura.clinic_delete_body')::jsonb,'{confirmation}','"wrong"'),'22023');
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,jsonb_set(current_setting('aura.clinic_delete_body')::jsonb,'{confirmed}','false'),'22023');
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,jsonb_set(current_setting('aura.clinic_delete_body')::jsonb,'{preview,id}',to_jsonb(current_setting('aura.clinic2'))),'40001');
reset role;
update public.aura_clinics set revision=revision+1 where id=current_setting('aura.delete_clinic_id')::uuid;
set local role authenticated;
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,current_setting('aura.clinic_delete_body')::jsonb,'40001');
reset role;
insert into public.aura_members(clinic_id,email,role) values(current_setting('aura.delete_clinic_id')::uuid,'security-two@example.invalid','manager');
set local role authenticated;
select pg_temp.as_user('2','aal2');
select set_config('aura.clinic_delete_preview',public.aura_rpc('delete_preview',current_setting('aura.delete_clinic_id')::uuid,'{}')::text,true);
select set_config('aura.clinic_delete_body',jsonb_build_object('confirmation','Clínica descartável','confirmed',true,'preview',current_setting('aura.clinic_delete_preview')::jsonb,'requestId',gen_random_uuid())::text,true);
reset role;
delete from public.aura_members where clinic_id=current_setting('aura.delete_clinic_id')::uuid and email='security-two@example.invalid';
set local role authenticated;
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,current_setting('aura.clinic_delete_body')::jsonb);
reset role;
insert into public.aura_members(clinic_id,email,role) values(current_setting('aura.delete_clinic_id')::uuid,'security-two@example.invalid','manager');
set local role authenticated;
select pg_temp.as_user('2','aal2');
select pg_temp.check_ok(public.aura_rpc('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,current_setting('aura.clinic_delete_body')::jsonb)->>'deleted'='true','partner with equal manager rights can delete confirmed clinic');
select pg_temp.denied('delete_clinic',current_setting('aura.delete_clinic_id')::uuid,current_setting('aura.clinic_delete_body')::jsonb);
select pg_temp.denied('get',current_setting('aura.delete_clinic_id')::uuid,'{}');
reset role;
select pg_temp.check_ok(not exists(select 1 from public.aura_clinics where id=current_setting('aura.delete_clinic_id')::uuid),'confirmed clinic physically removed');
select pg_temp.check_ok(not exists(select 1 from public.aura_history where clinic_id=current_setting('aura.delete_clinic_id')::uuid),'clinic history cascade removed');
select pg_temp.check_ok(not exists(select 1 from public.aura_members where clinic_id=current_setting('aura.delete_clinic_id')::uuid),'all clinic memberships cascade removed');
select pg_temp.check_ok(exists(select 1 from aura_private.platform_audit where action='clinic.delete' and target=current_setting('aura.delete_clinic_id')),'restricted audit kept');
select pg_temp.check_ok((select count(*)::text from auth.users)=current_setting('aura.keep_users'),'all login accounts preserved');
select pg_temp.check_ok((select count(*)::text from aura_private.licenses)=current_setting('aura.keep_licenses'),'all licenses preserved');
select pg_temp.check_ok((select jsonb_agg(to_jsonb(c) order by id)::text from public.aura_clinics c where id in (current_setting('aura.clinic1')::uuid,current_setting('aura.clinic2')::uuid))=current_setting('aura.preserved_clinics'),'all other clinic data unchanged');
-- A separate licensed identity can delete its only clinic and return to empty setup.
reset role;
select set_config('aura.only_uid',gen_random_uuid()::text,true),set_config('aura.only_sid',gen_random_uuid()::text,true),set_config('aura.only_clinic',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(current_setting('aura.only_uid')::uuid,'only-clinic@example.invalid',now(),false);
insert into auth.sessions(id,user_id,created_at,updated_at) values(current_setting('aura.only_sid')::uuid,current_setting('aura.only_uid')::uuid,now(),now());
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),current_setting('aura.only_uid')::uuid,'totp','verified',now(),now());
insert into aura_private.licenses(email,status) values('only-clinic@example.invalid','active');
insert into public.aura_clinics(id,owner_id,name,data) values(current_setting('aura.only_clinic')::uuid,current_setting('aura.only_uid')::uuid,'Única clínica','{}');
insert into public.aura_members(clinic_id,email,role) values(current_setting('aura.only_clinic')::uuid,'only-clinic@example.invalid','manager');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('aura.only_uid'),true),set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('aura.only_uid'),'session_id',current_setting('aura.only_sid'),'aal','aal2')::text,true);
do $t$begin begin delete from public.aura_clinics where id=current_setting('aura.only_clinic')::uuid;raise exception 'direct deletion bypassed RPC';exception when insufficient_privilege then perform pg_temp.check_ok(true,'direct table deletion blocked');end;end$t$;
select pg_temp.check_ok(public.aura_rpc('delete_clinic',current_setting('aura.only_clinic')::uuid,jsonb_build_object('confirmation','Única clínica','confirmed',true,'preview',public.aura_rpc('delete_preview',current_setting('aura.only_clinic')::uuid,'{}'),'requestId',gen_random_uuid()))->>'deleted'='true','only clinic deleted');
select pg_temp.check_ok(public.aura_rpc('get',null,'{}')->'data'='null'::jsonb and public.aura_rpc('get',null,'{}')->'clinics'='[]'::jsonb,'last clinic deletion returns empty clinic setup with account active');
reset role;
